{$ param section_1_title label="Section 1 Title" default="Menu" description="First section heading." $}
{$ param section_2_title label="Section 2 Title" default="" description="Second section heading (blank to hide)." $}
{$ param section_3_title label="Section 3 Title" default="" description="Third section heading (blank to hide)." $}

<nav class="ss-sidebar-nav mb-8" aria-label="Sidebar">
  {$ if section_1_title $}<div class="mb-6">
    <h3 class="ss-xsmall uppercase font-bold text-primary mb-2">{$= section_1_title $}</h3>
    <ul class="space-y-1 list-none">
      {$ slot section_1_links $}
        <li><a href="#">Example link</a></li>
      {$ /slot $}
    </ul>
  </div>{$ /if $}
  {$ if section_2_title $}<div class="mb-6">
    <h3 class="ss-xsmall uppercase font-bold text-primary mb-2">{$= section_2_title $}</h3>
    <ul class="space-y-1 list-none">
      {$ slot section_2_links $}
        <li><a href="#">Example link</a></li>
      {$ /slot $}
    </ul>
  </div>{$ /if $}
  {$ if section_3_title $}<div class="mb-6">
    <h3 class="ss-xsmall uppercase font-bold text-primary mb-2">{$= section_3_title $}</h3>
    <ul class="space-y-1 list-none">
      {$ slot section_3_links $}
        <li><a href="#">Example link</a></li>
      {$ /slot $}
    </ul>
  </div>{$ /if $}
</nav>
